import React, { useState, useEffect, useRef } from 'react';
import {
  Copy,
  ExternalLink,
  Image as ImageIcon,
  Check,
  AlertTriangle,
  RefreshCw,
  Upload,
  Link2,
  Undo2,
  Loader2,
  Wrench,
  ChevronRight,
  ChevronDown,
  Trash2,
  Play,
} from 'lucide-react';
import { VisualItem, VisualQueue, VisualCandidates, VisualState } from '../types';
import { api } from '../api/client';

/**
 * The infographic stage: the prompt out, the picture back.
 *
 * The picture is generated by hand, outside Jarvis, so this screen is a
 * hand-off in both directions rather than a queue of work the machine does.
 * Three things it must get right:
 *
 *   - Three ways to bring the picture back, because all three exist: paste
 *     (the natural gesture straight after generating), the downloaded file,
 *     and the link.
 *   - The exact words that must be on the picture, next to the picture.
 *     Nothing here can check that the text rendered, so the check goes where
 *     the only eye is -- and the tick is binding: no message carries a
 *     graphic without it.
 *   - Which graphics carry a claim about this business and which do not. A
 *     generic one says so on its own card, before it is sent.
 */
export const VisualQueueView: React.FC<{ onRefresh?: () => void }> = ({
  onRefresh,
}) => {
  const [data, setData] = useState<VisualQueue | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  // Only this one error has a button, so the flag is kept apart from the
  // message rather than inferred from it.
  const [missingTab, setMissingTab] = useState(false);
  const [repairing, setRepairing] = useState(false);
  const [repairNote, setRepairNote] = useState('');
  // Keyed by Lead ID, never by index: the queue is rebuilt from the server
  // and a row's position is not a stable address for it.
  const [busy, setBusy] = useState<Record<string, string>>({});
  const [notes, setNotes] = useState<Record<string, string>>({});
  const [urls, setUrls] = useState<Record<string, string>>({});
  const [copied, setCopied] = useState<string | null>(null);
  // Collapsed by default, and opening one does not open the rest: sixty
  // expanded cards is not a list anybody reads.
  const [open, setOpen] = useState<Record<string, boolean>>({});
  // Three of the four states need nothing from him, so the list opens on
  // the one that does. "Removed" is never part of All -- remove has to mean
  // gone from the list, or the button has not done what it says.
  const [filter, setFilter] = useState<VisualState | 'all'>('needs_image');

  const load = async () => {
    const res = await api.getVisualQueue();
    setMissingTab(!!res.missingTab);
    if (res.error) setError(res.error);
    else {
      setError(null);
      setData(res.data || null);
    }
    setLoading(false);
  };

  const repair = async () => {
    setRepairing(true);
    setRepairNote('');
    const res = await api.repairTabs();
    setRepairing(false);
    if (res.error) {
      setRepairNote(res.error);
      return;
    }
    setRepairNote(res.data?.note || 'Done.');
    // Reloading is the point: repairing and leaving the error on screen
    // reads as the button having done nothing.
    await load();
    onRefresh?.();
  };

  useEffect(() => {
    load();
  }, []);

  const say = (id: string, note: string) =>
    setNotes((prev) => ({ ...prev, [id]: note }));

  const work = async (id: string, label: string, fn: () => Promise<{ error?: string }>) => {
    setBusy((prev) => ({ ...prev, [id]: label }));
    say(id, '');
    const res = await fn();
    setBusy((prev) => ({ ...prev, [id]: '' }));
    if (res.error) say(id, res.error);
    else await load();
    return !res.error;
  };

  const attachFile = (id: string, file: File) => {
    // The browser already has the bytes, so a data URL avoids a multipart
    // form -- which matters most on a phone, where paste is the gesture and a
    // file picker is not.
    const reader = new FileReader();
    reader.onload = () =>
      work(id, 'Saving the picture', () =>
        api.attachVisual(id, { data_url: String(reader.result) })
      );
    reader.onerror = () => say(id, 'Could not read that file.');
    reader.readAsDataURL(file);
  };

  if (loading) {
    return (
      <div id="visual-loading" className="p-8 text-center text-slate-500 animate-pulse">
        Loading image prompts...
      </div>
    );
  }

  if (error) {
    return (
      <div id="visual-error" className="p-5 rounded-xl border border-amber-500/40 bg-amber-500/5 space-y-3">
        {/* pre-wrap: this message is several lines and the repair is the
            last of them, so collapsing the newlines would run the steps
            together into one paragraph. */}
        <p className="text-[13px] text-amber-200 whitespace-pre-wrap">{error}</p>
        {missingTab && (
          <div className="flex flex-wrap items-center gap-3">
            <button
              id="repair-tabs-btn"
              onClick={repair}
              disabled={repairing}
              className="inline-flex items-center gap-1.5 px-3.5 py-2 rounded-lg bg-emerald-500 text-slate-950 text-[12px] font-semibold hover:bg-emerald-400 studio-transition disabled:opacity-50"
            >
              <Wrench className="w-3.5 h-3.5" />
              {repairing ? 'Checking your Sheet...' : 'Add the missing tabs'}
            </button>
            {repairNote && (
              <span className="text-[12px] text-emerald-300">{repairNote}</span>
            )}
          </div>
        )}
      </div>
    );
  }

  if (!data?.enabled) {
    return (
      <div
        id="visual-off-card"
        className="p-10 text-center rounded-2xl border border-slate-800 bg-slate-900 space-y-2"
      >
        <div className="w-11 h-11 rounded-full bg-slate-800 text-slate-400 flex items-center justify-center mx-auto">
          <ImageIcon className="w-5 h-5" />
        </div>
        <h2 className="text-base font-semibold text-slate-100">
          This campaign pitches a page, not a picture
        </h2>
        <p className="text-[12px] text-slate-500 max-w-sm mx-auto">
          Switch the track to Infographic, or Both, in campaign settings and
          this step starts writing image prompts from the research you already
          have.
        </p>
      </div>
    );
  }

  if (!data.queue.length) {
    return (
      <div
        id="visual-empty-card"
        className="p-10 text-center rounded-2xl border border-slate-800 bg-slate-900 space-y-2"
      >
        <div className="w-11 h-11 rounded-full bg-emerald-500/10 text-emerald-400 flex items-center justify-center mx-auto">
          <ImageIcon className="w-5 h-5" />
        </div>
        <h2 className="text-base font-semibold text-slate-100">No image prompts yet</h2>
        <p className="text-[12px] text-slate-500 max-w-sm mx-auto">
          Nothing here yet. Run the Infographic step and it writes one prompt
          per researched lead, from the evidence already on the Sheet.
        </p>
      </div>
    );
  }

  const counts = data.counts || ({} as Record<string, number>);
  const shown = data.queue.filter((m) =>
    filter === 'all' ? m.state !== 'skipped' : m.state === filter
  );

  return (
    <div id="visual-queue-view" className="space-y-4">
      <div className="rounded-2xl border border-slate-800 bg-slate-900 p-5 flex flex-wrap items-start justify-between gap-3">
        <div className="min-w-0">
          <h1 className="text-base font-semibold text-slate-100 flex items-center gap-2">
            <ImageIcon className="w-4 h-4 text-emerald-400" />
            Infographic
          </h1>
          <p className="text-[12px] text-slate-500 mt-0.5">
            {counts.needs_image || 0} need a picture · {counts.needs_check || 0}{' '}
            need checking · {counts.ready || 0} ready to send
          </p>
        </div>
        {data.tool_url ? (
          <a
            id="visual-open-tool"
            href={data.tool_url}
            target="_blank"
            rel="noreferrer"
            className="inline-flex items-center gap-1.5 px-3.5 py-2 rounded-lg text-[13px] font-medium border border-slate-700 text-slate-300 hover:text-slate-100 hover:border-slate-600 hover:bg-slate-800/60 studio-transition"
          >
            Open {data.tool_name} <ExternalLink className="w-3.5 h-3.5" />
          </a>
        ) : null}
      </div>

      <CandidatePicker onStarted={() => onRefresh?.()} />

      <RotationPicker
        catalogue={data.catalogue}
        onSaved={() => load()}
      />

      <FilterBar
        counts={counts}
        active={filter}
        onPick={setFilter}
      />

      {shown.length === 0 && (
        <p id="visual-none-in-list" className="text-[12px] text-slate-500 px-1">
          Nothing in this list.
        </p>
      )}

      {shown.map((item) => (
        <VisualCard
          key={item.lead_id}
          item={item}
          open={!!open[item.lead_id]}
          onToggle={() =>
            setOpen((prev) => ({ ...prev, [item.lead_id]: !prev[item.lead_id] }))
          }
          toolName={data.tool_name}
          busy={busy[item.lead_id] || ''}
          note={notes[item.lead_id] || ''}
          url={urls[item.lead_id] || ''}
          copied={copied === item.lead_id}
          onCopy={() => {
            navigator.clipboard.writeText(item.prompt);
            setCopied(item.lead_id);
            setTimeout(() => setCopied(null), 2000);
          }}
          onUrl={(v) => setUrls((prev) => ({ ...prev, [item.lead_id]: v }))}
          onFile={(file) => attachFile(item.lead_id, file)}
          onFetchUrl={() => {
            const url = (urls[item.lead_id] || '').trim();
            if (!url) {
              say(item.lead_id, 'Paste the link first.');
              return;
            }
            work(item.lead_id, 'Fetching the picture', () =>
              api.attachVisual(item.lead_id, { url })
            );
          }}
          onConfirm={async () => {
            const ok = await work(item.lead_id, 'Saving', () =>
              api.confirmVisual(item.lead_id)
            );
            if (ok) onRefresh?.();
          }}
          onClear={() =>
            work(item.lead_id, 'Clearing', () => api.clearVisual(item.lead_id))
          }
          onDecide={(decision) =>
            work(item.lead_id, 'Saving', () =>
              api.decideVisual(item.lead_id, decision)
            )
          }
          onRegenerate={() =>
            work(item.lead_id, 'Writing a new prompt', () =>
              api.regenerateVisual(item.lead_id)
            )
          }
        />
      ))}
    </div>
  );
};

const STATE_WORDS: Record<string, string> = {
  needs_image: 'needs a picture',
  needs_check: 'needs checking',
  ready: 'ready to send',
  skipped: 'removed',
};

interface CardProps {
  item: VisualItem;
  open: boolean;
  onToggle: () => void;
  toolName: string;
  busy: string;
  note: string;
  url: string;
  copied: boolean;
  onCopy: () => void;
  onUrl: (value: string) => void;
  onFile: (file: File) => void;
  onFetchUrl: () => void;
  onConfirm: () => void;
  onClear: () => void;
  onDecide: (decision: 'Skip' | 'Approved') => void;
  onRegenerate: () => void;
}

const VisualCard: React.FC<CardProps> = ({
  item,
  open,
  onToggle,
  toolName,
  busy,
  note,
  url,
  copied,
  onCopy,
  onUrl,
  onFile,
  onFetchUrl,
  onConfirm,
  onClear,
  onDecide,
  onRegenerate,
}) => {
  const fileRef = useRef<HTMLInputElement>(null);
  // A broken-image icon beside "the words are right" is the worst thing this
  // card could show: it invites a tick on a picture nobody can see.
  const [imageFailed, setImageFailed] = useState(false);
  // Cache-busting so a replaced picture is not served from the browser's copy
  // of the one it replaced -- the URL is the same, and looking at the old
  // image while ticking that its words are right is the worst version of
  // this screen.
  const src = `/api/screenshot/${encodeURIComponent(item.lead_id)}?v=${encodeURIComponent(
    item.state
  )}`;

  return (
    <div
      id={`visual-item-${item.lead_id}`}
      className={`rounded-2xl border border-slate-800 bg-slate-900 ${
        open ? 'p-5 space-y-4' : 'px-4 py-3'
      }`}
    >
      {/* The header carries everything needed to decide whether to open one:
          who it is, what it is waiting for, and whether it claims anything
          about them. */}
      <button
        id={`visual-head-${item.lead_id}`}
        onClick={onToggle}
        aria-expanded={open}
        className="w-full flex flex-wrap items-center gap-2 text-left"
      >
        <span className="shrink-0 text-emerald-400">
          {open ? (
            <ChevronDown className="w-4 h-4" />
          ) : (
            <ChevronRight className="w-4 h-4" />
          )}
        </span>
        <span className="text-[14px] font-semibold text-slate-100 truncate min-w-0">
          {item.business_name}
        </span>
        <span className="text-[11px] text-slate-500">
          {STATE_WORDS[item.state] || item.state}
        </span>
        {item.specific ? (
          <span className="shrink-0 text-[11px] px-2 py-0.5 rounded-full bg-emerald-500/15 text-emerald-300">
            Named
          </span>
        ) : (
          <span className="shrink-0 text-[11px] px-2 py-0.5 rounded-full bg-amber-500/15 text-amber-300 inline-flex items-center gap-1">
            <AlertTriangle className="w-3 h-3" />
            Generic
          </span>
        )}
      </button>

      {!open ? null : (
      <>
      <p className="text-[11px] text-slate-500">
        {item.style} / {item.layout}
        {item.category ? ` · ${item.category}` : ''}
        {item.specific ? '' : ' · not enough evidence to name them'}
      </p>

      <details>
        <summary className="text-[12px] text-slate-400 cursor-pointer">
          Why these cards — the evidence behind each one
        </summary>
        <pre className="mt-2 p-3 rounded-lg bg-slate-950 border border-slate-800 text-[11px] text-slate-300 whitespace-pre-wrap font-mono">
          {item.gaps || 'No evidence recorded.'}
        </pre>
      </details>

      <div className="p-3 rounded-lg bg-slate-950 border border-slate-800 text-[11px] text-emerald-200/90 font-mono max-h-40 overflow-y-auto whitespace-pre-wrap leading-relaxed">
        {item.prompt}
      </div>

      <div className="flex flex-wrap gap-2">
        <button
          onClick={onCopy}
          className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg bg-emerald-500 text-slate-950 text-[12px] font-semibold hover:bg-emerald-400 studio-transition"
        >
          <Copy className="w-3.5 h-3.5" />
          {copied ? 'Copied' : `Copy prompt for ${toolName || 'the image tool'}`}
        </button>
        <button
          onClick={onRegenerate}
          disabled={!!busy}
          className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg border border-slate-700 text-slate-300 text-[12px] hover:bg-slate-800/60 studio-transition disabled:opacity-50"
        >
          {busy === 'Writing a new prompt' ? (
            <Loader2 className="w-3.5 h-3.5 animate-spin" />
          ) : (
            <RefreshCw className="w-3.5 h-3.5" />
          )}
          Different look
        </button>
        {item.state === 'skipped' ? (
          <button
            onClick={() => onDecide('Approved')}
            disabled={!!busy}
            className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg border border-slate-700 text-slate-300 text-[12px] hover:bg-slate-800/60 studio-transition disabled:opacity-50"
          >
            <Undo2 className="w-3.5 h-3.5" />
            Put it back
          </button>
        ) : (
          <button
            onClick={() => onDecide('Skip')}
            disabled={!!busy}
            className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg border border-slate-700 text-slate-400 text-[12px] hover:bg-slate-800/60 studio-transition disabled:opacity-50"
          >
            <Trash2 className="w-3.5 h-3.5" />
            Remove
          </button>
        )}
      </div>

      {item.state === 'skipped' && (
        <p className="text-[12px] text-slate-500">
          Removed. This lead is messaged with the page instead, not held
          waiting for a picture.
        </p>
      )}

      {item.state === 'needs_image' && (
        <div className="space-y-2">
          <div
            id={`visual-drop-${item.lead_id}`}
            tabIndex={0}
            onPaste={(e) => {
              const items = e.clipboardData?.items || [];
              for (let i = 0; i < items.length; i += 1) {
                if (items[i].type?.startsWith('image/')) {
                  e.preventDefault();
                  const file = items[i].getAsFile();
                  if (file) onFile(file);
                  return;
                }
              }
            }}
            onDragOver={(e) => e.preventDefault()}
            onDrop={(e) => {
              e.preventDefault();
              const file = e.dataTransfer?.files?.[0];
              if (file) onFile(file);
            }}
            onClick={() => fileRef.current?.click()}
            className="p-5 rounded-xl border border-dashed border-slate-700 text-center text-[12px] text-slate-400 cursor-pointer hover:border-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-emerald-500"
          >
            <Upload className="w-4 h-4 mx-auto mb-1.5 text-slate-500" />
            Click here and press Ctrl+V to paste the picture, drop the file
            here, or click to choose it.
          </div>
          <input
            ref={fileRef}
            type="file"
            accept="image/png,image/jpeg,image/webp"
            className="hidden"
            onChange={(e) => {
              const file = e.target.files?.[0];
              if (file) onFile(file);
            }}
          />
          <div className="flex flex-wrap gap-2">
            <input
              type="url"
              value={url}
              onChange={(e) => onUrl(e.target.value)}
              placeholder="...or right-click the picture, Copy image address, paste here"
              className="flex-1 min-w-[14rem] px-3 py-2 rounded-lg bg-slate-950 border border-slate-700 text-[13px] text-slate-100"
            />
            <button
              onClick={onFetchUrl}
              disabled={!!busy}
              className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg border border-slate-700 text-slate-300 text-[12px] hover:bg-slate-800/60 studio-transition disabled:opacity-50"
            >
              <Link2 className="w-3.5 h-3.5" />
              Fetch it
            </button>
          </div>
          <p className="text-[11px] text-slate-500">
            The link has to be the <strong>picture&apos;s</strong> own address,
            not the page it sits on — right-click the image and choose{' '}
            <strong>Copy image address</strong>. If the picture is only
            visible while you are signed in, this cannot reach it: save it and
            paste the file, which always works.
          </p>
        </div>
      )}

      {(item.state === 'needs_check' || item.state === 'ready') && (
        <div className="space-y-3">
          {imageFailed ? (
            <p
              id={`visual-noimage-${item.lead_id}`}
              className="text-[12px] text-amber-300"
            >
              The picture is recorded but could not be loaded here. Press Wrong
              picture and paste it again rather than ticking words you cannot
              see.
            </p>
          ) : (
            <>
              <img
                src={src}
                alt=""
                onError={() => setImageFailed(true)}
                // Shown at about the width WhatsApp gives a picture in a chat.
                // A graphic that reads at full size and not at this one is a
                // graphic nobody will read.
                className="block w-[260px] max-w-full rounded-lg border border-slate-800"
              />
              <p className="text-[11px] text-slate-500">
                Shown at about the size WhatsApp gives it in a chat. If it is
                not readable here, it is not readable there.
              </p>
            </>
          )}
          {/* Set apart from the message below it: the two were read as one
              thing, and only one of them is ever sent. */}
          <div className="p-3 rounded-lg border border-amber-900/40 bg-amber-950/20">
            <p className="text-[12px] text-slate-200 font-medium">
              Proofread the picture
            </p>
            <p className="text-[11px] text-slate-500">
              These are the words the prompt asked for. Check they appear on
              the image above and are spelled right — nothing here can see the
              picture, so this is the one thing only you can do.
            </p>
            <pre className="mt-2 p-3 rounded-lg bg-slate-950 border border-slate-800 text-[12px] text-slate-200 whitespace-pre-wrap font-mono">
              {item.expected_text.join('\n') || 'No text recorded.'}
            </pre>
            <p className="text-[11px] text-amber-300/80 mt-2">
              This is <strong>not</strong> the message. It is never sent
              anywhere — it is only here to compare against the picture.
            </p>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            {item.state === 'ready' ? (
              <span className="inline-flex items-center gap-1.5 text-[12px] text-emerald-300">
                <Check className="w-3.5 h-3.5" />
                Picture checked.
              </span>
            ) : (
              <button
                onClick={onConfirm}
                disabled={!!busy}
                className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg bg-emerald-500 text-slate-950 text-[12px] font-semibold hover:bg-emerald-400 studio-transition disabled:opacity-50"
              >
                <Check className="w-3.5 h-3.5" />
                The words are right
              </button>
            )}
            <button
              onClick={onClear}
              disabled={!!busy}
              className="px-3 py-2 rounded-lg border border-slate-700 text-slate-400 text-[12px] hover:bg-slate-800/60 studio-transition disabled:opacity-50"
            >
              Wrong picture
            </button>
          </div>

          {item.state === 'ready' && <VisualMessage item={item} />}
        </div>
      )}

      {(busy || note) && (
        <p
          className={`text-[12px] ${note ? 'text-amber-300' : 'text-slate-500'} whitespace-pre-wrap`}
        >
          {note || `${busy}...`}
        </p>
      )}
      </>
      )}
    </div>
  );
};


/**
 * Which looks are in the rotation.
 *
 * Drawn from what the server says exists rather than a list written out here:
 * a name typed twice drifts from the one the server will accept, and the
 * mismatch only ever shows up as a refused save.
 *
 * Both lists feed every industry's ring, so unticking a style removes it
 * everywhere -- which is the point. Ticking nothing means all of them.
 */
const RotationPicker: React.FC<{
  catalogue: VisualQueue['catalogue'];
  onSaved: () => void;
}> = ({ catalogue, onSaved }) => {
  const [open, setOpen] = useState(false);
  const [styles, setStyles] = useState<string[]>(catalogue.chosen_styles);
  const [layouts, setLayouts] = useState<string[]>(catalogue.chosen_layouts);
  const [note, setNote] = useState('');
  const [bad, setBad] = useState(false);
  const [saving, setSaving] = useState(false);

  const toggle = (
    list: string[],
    set: (v: string[]) => void,
    name: string,
  ) => set(list.includes(name) ? list.filter((n) => n !== name) : [...list, name]);

  const boxes = (
    all: string[],
    chosen: string[],
    set: (v: string[]) => void,
    group: string,
  ) => (
    <div className="flex flex-wrap gap-x-4 gap-y-2">
      {all.map((name) => (
        <label
          key={name}
          className="flex items-center gap-1.5 text-[12px] text-slate-300"
        >
          <input
            type="checkbox"
            data-rotation={group}
            value={name}
            checked={chosen.includes(name)}
            onChange={() => toggle(chosen, set, name)}
          />
          {name}
        </label>
      ))}
    </div>
  );

  if (!open) {
    return (
      <button
        id="rotation-toggle"
        onClick={() => setOpen(true)}
        className="text-[12px] text-slate-400 hover:text-slate-200 studio-transition"
      >
        Which looks are in the rotation
      </button>
    );
  }

  return (
    <div
      id="rotation-picker"
      className="rounded-2xl border border-slate-800 bg-slate-900 p-5 space-y-3"
    >
      <div>
        <h2 className="text-[13px] font-semibold text-slate-100">
          Which looks are in the rotation
        </h2>
        <p className="text-[11px] text-slate-500 mt-0.5">
          Each industry rotates through its own pairs and never repeats the
          previous lead&apos;s, so ten salons in a row do not all get the same
          graphic. Unticking here narrows every industry at once. Tick none and
          all of them stay in play.
        </p>
      </div>
      <div>
        <p className="text-[12px] font-medium text-slate-300 mb-1.5">Style</p>
        {boxes(catalogue.styles, styles, setStyles, 'styles')}
      </div>
      <div>
        <p className="text-[12px] font-medium text-slate-300 mb-1.5">Layout</p>
        {boxes(catalogue.layouts, layouts, setLayouts, 'layouts')}
      </div>
      <div className="flex flex-wrap items-center gap-3">
        <button
          id="save-rotation-btn"
          onClick={async () => {
            setSaving(true);
            setNote('');
            const res = await api.setVisualRotation(styles, layouts);
            setSaving(false);
            setBad(!!res.error);
            setNote(
              res.error ||
                'Saved. New prompts use it; press Different look to re-roll one you already have.',
            );
            if (!res.error) onSaved();
          }}
          disabled={saving}
          className="px-3.5 py-2 rounded-lg bg-emerald-500 text-slate-950 text-[12px] font-semibold hover:bg-emerald-400 studio-transition disabled:opacity-50"
        >
          {saving ? 'Saving...' : 'Save rotation'}
        </button>
        <button
          onClick={() => setOpen(false)}
          className="text-[12px] text-slate-400 hover:text-slate-200"
        >
          Close
        </button>
        {note && (
          <span
            className={`text-[12px] ${bad ? 'text-amber-300' : 'text-emerald-300'}`}
          >
            {note}
          </span>
        )}
      </div>
    </div>
  );
};


/**
 * Which list is showing.
 *
 * Three of the four states need nothing from him, so the default is the one
 * that does. "Removed" is never part of All: remove has to mean gone from
 * the list, or the button has not done what it says.
 */
const FilterBar: React.FC<{
  counts: Record<string, number>;
  active: VisualState | 'all';
  onPick: (f: VisualState | 'all') => void;
}> = ({ counts, active, onPick }) => {
  const live =
    (counts.needs_image || 0) + (counts.needs_check || 0) + (counts.ready || 0);
  const tabs: [VisualState | 'all', string, number][] = [
    ['needs_image', 'Need a picture', counts.needs_image || 0],
    ['needs_check', 'Need checking', counts.needs_check || 0],
    ['ready', 'Ready to send', counts.ready || 0],
    ['all', 'All', live],
    ['skipped', 'Removed', counts.skipped || 0],
  ];
  return (
    <div id="visual-filters" className="flex flex-wrap gap-2">
      {tabs.map(([key, label, n]) => (
        <button
          key={key}
          id={`visual-filter-${key}`}
          onClick={() => onPick(key)}
          disabled={!n}
          className={`px-3 py-1.5 rounded-lg text-[12px] border studio-transition disabled:opacity-40 disabled:cursor-not-allowed ${
            active === key
              ? 'border-emerald-500/50 bg-emerald-500/10 text-emerald-200'
              : 'border-slate-700 text-slate-400 hover:bg-slate-800/60'
          }`}
        >
          {label} ({n})
        </button>
      ))}
    </div>
  );
};

/**
 * Who a run would write for, split by how they can be contacted.
 *
 * Each prompt is a visit to the image tool and a picture to read, so a batch
 * of sixty is a week rather than a morning. A limit alone bounds the cost
 * but picks whichever leads come first, which is not the same as picking the
 * ones worth starting with -- so the groups come first, and ticking exact
 * businesses is the precise version of the same thing.
 */
const CandidatePicker: React.FC<{ onStarted: () => void }> = ({ onStarted }) => {
  const [data, setData] = useState<VisualCandidates | null>(null);
  const [limit, setLimit] = useState(10);
  const [picked, setPicked] = useState<Record<string, boolean>>({});
  const [note, setNote] = useState('');
  const [bad, setBad] = useState(false);
  const [starting, setStarting] = useState(false);

  const load = async () => {
    const res = await api.getVisualCandidates();
    if (res.data) setData(res.data);
  };

  useEffect(() => {
    load();
  }, []);

  const start = async (groups: string[], leadIds: string[]) => {
    setStarting(true);
    setNote('');
    const res = await api.runVisual(groups, leadIds, limit || null);
    setStarting(false);
    setBad(!!res.error);
    setNote(res.error || `${res.data?.running || 'Started'} running...`);
    if (!res.error) {
      setPicked({});
      onStarted();
    }
  };

  if (!data?.enabled) return null;
  if (!data.total) {
    return (
      <p id="visual-no-candidates" className="text-[12px] text-slate-500 px-1">
        Every researched lead already has a prompt.
      </p>
    );
  }

  const tickedCount = Object.keys(picked).length;

  return (
    <div
      id="visual-candidates"
      className="rounded-2xl border border-slate-800 bg-slate-900 p-5 space-y-3"
    >
      <div className="flex flex-wrap items-center justify-between gap-3">
        <h2 className="text-[13px] font-semibold text-slate-100">Who to write for</h2>
        <label className="flex items-center gap-2 text-[12px] text-slate-400">
          How many
          <input
            id="visual-limit"
            type="number"
            min={1}
            max={500}
            value={limit}
            onChange={(e) => setLimit(Number(e.target.value))}
            className="w-20 px-2 py-1 rounded-lg bg-slate-950 border border-slate-700 text-[13px] text-slate-100"
          />
        </label>
      </div>
      <p className="text-[11px] text-slate-500">
        Each prompt is a visit to the image tool and a picture to read, so a
        batch of sixty is a week, not a morning. Pick the group worth starting
        with — or tick the exact businesses — and it writes that many and stops.
      </p>

      {data.groups
        .filter((g) => g.count > 0)
        .map((g) => (
          <details key={g.key} id={`visual-group-${g.key}`} className="rounded-lg">
            <summary className="flex flex-wrap items-center gap-2 cursor-pointer text-[13px] text-slate-200">
              <span className="font-medium">{g.label}</span>
              <span className="text-slate-500">— {g.count}</span>
              {g.second_approach && (
                <span className="text-[11px] px-2 py-0.5 rounded-full bg-amber-500/15 text-amber-300">
                  second approach
                </span>
              )}
              {g.contactable ? (
                <button
                  id={`visual-run-${g.key}`}
                  onClick={(e) => {
                    e.preventDefault();
                    start([g.key], []);
                  }}
                  disabled={starting}
                  className="inline-flex items-center gap-1.5 ml-auto px-3 py-1.5 rounded-lg bg-emerald-500 text-slate-950 text-[12px] font-semibold hover:bg-emerald-400 studio-transition disabled:opacity-50"
                >
                  <Play className="w-3 h-3" />
                  Write for this group
                </button>
              ) : (
                <span className="ml-auto text-[11px] text-slate-500">
                  nothing can be written for these yet
                </span>
              )}
            </summary>
            <div className="flex flex-wrap gap-x-4 gap-y-1.5 mt-2 ml-5">
              {g.leads.map((l) => (
                <label
                  key={l.lead_id}
                  className="flex items-center gap-1.5 text-[12px] text-slate-400"
                >
                  <input
                    type="checkbox"
                    data-pick
                    value={l.lead_id}
                    checked={!!picked[l.lead_id]}
                    onChange={(e) =>
                      setPicked((prev) => {
                        const next = { ...prev };
                        if (e.target.checked) next[l.lead_id] = true;
                        else delete next[l.lead_id];
                        return next;
                      })
                    }
                  />
                  {l.name}
                </label>
              ))}
              {g.capped && <span className="text-[11px] text-slate-600">...and more</span>}
            </div>
          </details>
        ))}

      <div className="flex flex-wrap items-center gap-3 pt-1">
        <button
          id="visual-run-picked"
          onClick={() => start([], Object.keys(picked))}
          disabled={starting || !tickedCount}
          className="px-3.5 py-2 rounded-lg border border-slate-700 text-slate-200 text-[12px] hover:bg-slate-800/60 studio-transition disabled:opacity-40"
        >
          Write for the ones I ticked
        </button>
        <span id="visual-picked-note" className="text-[12px] text-slate-500">
          {tickedCount ? `${tickedCount} ticked` : 'Nothing ticked yet'}
        </span>
        {note && (
          <span className={`text-[12px] ${bad ? 'text-amber-300' : 'text-emerald-300'}`}>
            {note}
          </span>
        )}
      </div>
    </div>
  );
};


/**
 * What actually gets sent, shown where the question is asked.
 *
 * The proofreading box above it was read as the message -- a fair reading of
 * "these exact words", and the kind of mistake you only make once a graphic
 * has reached a real business. So the real text is here, on the same card,
 * and it says where it sends from: there is no send button on this step.
 */
/**
 * A business contacted before, now with a picture and no way to say so.
 *
 * The draft stage never touches a lead that already has an Outreach Log row
 * -- which is what stops a business being written to twice, and also meant
 * its graphic could never get a message. This button is the one way through:
 * it clears the send status and rewrites the message about the picture.
 */
const AlreadyMessaged: React.FC<{ item: VisualItem }> = ({ item }) => {
  const [busy, setBusy] = useState(false);
  const [note, setNote] = useState('');
  const [done, setDone] = useState(false);

  return (
    <div
      id={`visual-sent-${item.lead_id}`}
      className="p-3 rounded-lg border border-slate-700 bg-slate-950/60 space-y-2"
    >
      <p className="text-[12px] text-slate-300 font-medium">
        Already messaged on {item.sent_at}, with this:
      </p>
      <pre className="text-[12px] text-slate-400 whitespace-pre-wrap font-mono">
        {item.message}
      </pre>
      <p className="text-[11px] text-slate-500">
        That was the old message. Write a new one about this picture and the
        lead goes back into Review &amp; Send, with the graphic attached. The
        picture and the prompt are kept.
      </p>
      <div className="flex flex-wrap items-center gap-3">
        <button
          id={`visual-redraft-${item.lead_id}`}
          onClick={async () => {
            setBusy(true);
            setNote('');
            const res = await api.redraftVisual(item.lead_id);
            setBusy(false);
            if (res.error) setNote(res.error);
            else setDone(true);
          }}
          disabled={busy || done}
          className="px-3.5 py-2 rounded-lg bg-emerald-500 text-slate-950 text-[12px] font-semibold hover:bg-emerald-400 studio-transition disabled:opacity-50"
        >
          {busy ? 'Writing...' : 'Write a new message for this picture'}
        </button>
        {done && (
          <span className="text-[12px] text-emerald-300">
            Written. It is back in Review &amp; Send.
          </span>
        )}
        {note && <span className="text-[12px] text-amber-300">{note}</span>}
      </div>
    </div>
  );
};

const VisualMessage: React.FC<{ item: VisualItem }> = ({ item }) => {
  if (item.sent_at) {
    return <AlreadyMessaged item={item} />;
  }
  if (!item.message) {
    return (
      <div
        id={`visual-undrafted-${item.lead_id}`}
        className="p-3 rounded-lg border border-emerald-900/40 bg-emerald-950/20"
      >
        <p className="text-[12px] text-slate-200 font-medium">
          Next: its message has not been written yet
        </p>
        <p className="text-[11px] text-slate-500 mt-1">
          Run the draft step and this business gets its own message, written
          from its own research — exactly like the website ones. The picture
          above is attached to it. It then sends from Review &amp; Send, the
          same queue as everything else.
        </p>
      </div>
    );
  }
  return (
    <div
      id={`visual-message-${item.lead_id}`}
      className="p-3 rounded-lg border border-emerald-900/40 bg-emerald-950/20 space-y-2"
    >
      <p className="text-[12px] text-slate-200 font-medium">
        The message this picture goes out with
      </p>
      <p className="text-[11px] text-slate-500">
        Written for this business, and editable in Review &amp; Send before it
        goes.
      </p>
      <pre className="p-3 rounded-lg bg-slate-950 border border-slate-800 text-[12px] text-slate-200 whitespace-pre-wrap font-mono">
        {item.message}
      </pre>
      <p className="text-[11px] text-slate-500">
        It sends from <strong>Review &amp; Send</strong>, the same queue as the
        website messages. There is no separate send button here.
      </p>
    </div>
  );
};
